const PR26=[{label:"Ví dụ: push, top, pop",input:"",code:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    stack<int> st;\n    st.push(3);\n    st.push(1);\n    st.push(4);\n    cout << \"dinh: \" << st.top() << \"\\n\";\n    st.pop();\n    st.push(5);\n    while (!st.empty()) {\n        cout << st.top() << \" \";\n        st.pop();\n    }\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"st"}],py:{code:"st = []\nst.append(3)\nst.append(1)\nst.append(4)\nprint(\"dinh:\", st[-1])\nst.pop()\nst.append(5)\nwhile st:\n    print(st.pop(), end=\" \")\nprint()",viz:[{type:"cont",of:"st",as:"stack"}],note:"list của Python dùng làm ngăn xếp: đỉnh là phần tử cuối. pop() vừa bỏ vừa trả về phần tử đỉnh. Lấy hết ra thì được thứ tự ngược: 5 1 3."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        Stack<int> st = new Stack<int>();\n        st.Push(3);\n        st.Push(1);\n        st.Push(4);\n        Console.WriteLine(\"dinh: \" + st.Peek());\n        st.Pop();\n        st.Push(5);\n        while (st.Count > 0)\n        {\n            Console.Write(st.Pop() + \" \");\n        }\n        Console.WriteLine();\n    }\n}",viz:[{type:"cont",of:"st",as:"stack"}],note:"Phần tử đỉnh luôn ở trên cùng. Pop() vừa bỏ vừa trả về phần tử đỉnh. Lấy hết ra thì được thứ tự ngược với thứ tự đặt vào: 5 1 3."}},{label:"Ví dụ: Kiểm tra dấu ngoặc",input:"{[()()]}",code:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    cin >> s;\n    stack<char> st;\n    bool ok = true;\n    for (int i = 0; i < (int)s.size() && ok; i++) {\n        char c = s[i];\n        if (c == '(' || c == '[' || c == '{') {\n            st.push(c);\n        } else {\n            char mo = c == ')' ? '(' : c == ']' ? '[' : '{';\n            if (st.empty() || st.top() != mo) ok = false;\n            else st.pop();\n        }\n    }\n    if (!st.empty()) ok = false;\n    cout << (ok ? \"YES\" : \"NO\") << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"cont",of:"st"}],py:{code:"s = input()\nst = []\nok = True\ncap = {\")\": \"(\", \"]\": \"[\", \"}\": \"{\"}\nfor c in s:\n    if c in \"([{\":\n        st.append(c)\n    elif not st or st[-1] != cap[c]:\n        ok = False\n        break\n    else:\n        st.pop()\nif st:\n    ok = False\nprint(\"YES\" if ok else \"NO\")",viz:[{type:"cont",of:"st",as:"stack"}],note:"Mỗi dấu mở được đặt lên ngăn xếp; mỗi dấu đóng gặp đúng dấu mở cùng loại ở đỉnh thì cả hai cùng biến mất. dict cap cho biết dấu mở tương ứng với mỗi dấu đóng. Thử ([)] và (()."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        Stack<char> st = new Stack<char>();\n        bool ok = true;\n        for (int i = 0; i < s.Length && ok; i++)\n        {\n            char c = s[i];\n            if (c == '(' || c == '[' || c == '{')\n            {\n                st.Push(c);\n            }\n            else\n            {\n                char mo = c == ')' ? '(' : c == ']' ? '[' : '{';\n                if (st.Count == 0 || st.Peek() != mo) ok = false;\n                else st.Pop();\n            }\n        }\n        if (st.Count > 0) ok = false;\n        Console.WriteLine(ok ? \"YES\" : \"NO\");\n    }\n}",viz:[{type:"cells",of:"s",ptr:["i"]},{type:"cont",of:"st",as:"stack"}]}},{label:"Ví dụ: Tính biểu thức hậu tố",input:"3 4 + 2 * 10 -",code:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    stack<long long> st;\n    string tk;\n    while (cin >> tk) {\n        if (tk == \"+\" || tk == \"-\" || tk == \"*\") {\n            long long b = st.top(); st.pop();     // lấy ra trước là toán hạng bên phải\n            long long a = st.top(); st.pop();\n            if (tk == \"+\") st.push(a + b);\n            else if (tk == \"-\") st.push(a - b);\n            else st.push(a * b);\n        } else {\n            st.push(stoll(tk));\n        }\n    }\n    cout << st.top() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"st"},{type:"vars",names:["tk"]}],py:{code:"st = []\nfor tk in input().split():\n    if tk in (\"+\", \"-\", \"*\"):\n        b = st.pop()      # lấy ra trước là toán hạng bên phải\n        a = st.pop()\n        if tk == \"+\":\n            st.append(a + b)\n        elif tk == \"-\":\n            st.append(a - b)\n        else:\n            st.append(a * b)\n    else:\n        st.append(int(tk))\nprint(st[-1])",viz:[{type:"cont",of:"st",as:"stack"},{type:"vars",names:["tk"]}]},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        Stack<long> st = new Stack<long>();\n        foreach (string tk in Console.ReadLine().Split())\n        {\n            if (tk == \"+\" || tk == \"-\" || tk == \"*\")\n            {\n                long b = st.Pop();     // lấy ra trước là toán hạng bên phải\n                long a = st.Pop();\n                if (tk == \"+\") st.Push(a + b);\n                else if (tk == \"-\") st.Push(a - b);\n                else st.Push(a * b);\n            }\n            else\n            {\n                st.Push(long.Parse(tk));\n            }\n        }\n        Console.WriteLine(st.Peek());\n    }\n}",viz:[{type:"cont",of:"st",as:"stack"},{type:"vars",names:["tk"]}]}},{label:"Ví dụ: Ngăn xếp tự cài bằng mảng",input:"",code:"#include <iostream>\nusing namespace std;\n\nint st[100];\nint top = 0;          // số phần tử đang có; đỉnh là st[top - 1]\n\nvoid push(int x) { st[top++] = x; }\nvoid pop() { top--; }\n\nint main() {\n    push(3);\n    push(1);\n    push(4);\n    pop();\n    push(5);\n    cout << st[top - 1] << \" \" << top << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"st",range:["0","top-1"],ptr:["top"]}],py:{code:"st = [0] * 100\ntop = 0          # số phần tử đang có; đỉnh là st[top - 1]\n\ndef push(x):\n    global top\n    st[top] = x\n    top += 1\n\ndef pop():\n    global top\n    top -= 1\n\npush(3)\npush(1)\npush(4)\npop()\npush(5)\nprint(st[top - 1], top)",note:"Python ít khi cần cách này vì list đã có append/pop O(1); nhưng đây chính là cách list làm bên trong. Vùng sáng là phần đang dùng, từ 0 tới top − 1. Sau pop, số 4 vẫn còn trong mảng nhưng nằm ngoài vùng sáng; push(5) ghi đè lên nó."},cs:{code:"using System;\n\nclass Program\n{\n    static int[] st = new int[100];\n    static int top = 0;          // số phần tử đang có; đỉnh là st[top - 1]\n\n    static void Push(int x) { st[top++] = x; }\n    static void Pop() { top--; }\n\n    static void Main()\n    {\n        Push(3);\n        Push(1);\n        Push(4);\n        Pop();\n        Push(5);\n        Console.WriteLine(st[top - 1] + \" \" + top);\n    }\n}"}},{label:"Lỗi: lấy từ ngăn xếp rỗng",input:"",code:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s = \"())\";\n    stack<char> st;\n    for (char c : s) {\n        if (c == '(') st.push(c);\n        else st.pop();          // thiếu kiểm tra st.empty()\n    }\n    cout << st.size() << \"\\n\";\n    return 0;\n}",viz:[{type:"cont",of:"st"}],py:{code:"s = \"())\"\nst = []\nfor c in s:\n    if c == \"(\":\n        st.append(c)\n    else:\n        st.pop()          # thiếu kiểm tra st có rỗng không\nprint(len(st))",viz:[{type:"cont",of:"st",as:"stack"}],note:"Dấu ) thứ hai đến khi list đã rỗng: pop() báo IndexError: pop from empty list. Đúng ra phải kiểm tra if st: trước, và gặp trường hợp này thì kết luận dãy sai."},cs:{code:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = \"())\";\n        Stack<char> st = new Stack<char>();\n        foreach (char c in s)\n        {\n            if (c == '(') st.Push(c);\n            else st.Pop();          // thiếu kiểm tra st.Count > 0\n        }\n        Console.WriteLine(st.Count);\n    }\n}",viz:[{type:"cont",of:"st",as:"stack"}],note:"Dấu ) thứ hai đến khi ngăn xếp đã rỗng: Pop() ném InvalidOperationException (Stack empty). Đúng ra phải kiểm tra st.Count > 0 trước, và gặp trường hợp này thì kết luận dãy sai."}}];
