makeEx2(document.getElementById("ex-l26"),sim26,[{t:"Dãy ngoặc đúng",d:"Đầu vào: một xâu s gồm các ký tự ( ) [ ] { } (1 ≤ độ dài ≤ 10^5). Đầu ra: YES nếu s là dãy ngoặc đúng, ngược lại NO.",tests:[{in:"{[()()]}",out:"YES"},{in:"([)]",out:"NO"},{in:"(()",out:"NO"},{in:"())",out:"NO"},{in:"()[]{}",out:"YES"},{in:")(",out:"NO"},{in:"((((((((((((((((((()))))))))))))))))))",out:"YES"},{in:"{{{{{{{{{{{{{{{{{{{{{{{{{{{{{{}}}}}}}}}}}}}}}}}}}}}}}}}}}}})",out:"NO"}],start:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    cin >> s;\n    // dấu mở: push; dấu đóng: đỉnh phải là dấu mở cùng loại\n    cout << \"NO\" << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"(".repeat(n/2)+")".repeat(n/2),ns:[500,2000,8000],need:"n",limit:n=>40*n+200,why:"Xóa dần các cặp kề nhau cho tới khi hết tốn O(n²) với dãy lồng sâu. Ngăn xếp chỉ duyệt một lần."},py:{start:"s = input()\n# dấu mở: append; dấu đóng: đỉnh phải là dấu mở cùng loại\nprint(\"NO\")",hints:["Gặp dấu mở thì append. Gặp dấu đóng: nếu list rỗng, hoặc st[-1] không phải dấu mở cùng loại, thì dãy sai; ngược lại pop.","Đọc hết xâu mà list còn phần tử thì cũng sai.","Lặp s = s.replace(\"()\", \"\") cho tới khi không đổi cũng đúng nhưng O(n²) với dãy lồng sâu."]},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        // dấu mở: Push; dấu đóng: đỉnh phải là dấu mở cùng loại\n        Console.WriteLine(\"NO\");\n    }\n}",hints:["Gặp dấu mở thì Push. Gặp dấu đóng: nếu ngăn xếp rỗng, hoặc Peek() không phải dấu mở cùng loại, thì dãy sai; ngược lại Pop.","Đọc hết xâu mà ngăn xếp còn phần tử thì cũng sai.","Mỗi ký tự vào, ra ngăn xếp nhiều nhất một lần: O(n)."]}},{t:"Tính biểu thức hậu tố",d:"Đầu vào: một dòng là biểu thức hậu tố, các ký hiệu cách nhau một dấu cách; gồm số nguyên không âm và các phép + − *. Biểu thức luôn hợp lệ; mọi kết quả trung gian nằm trong khoảng ±10^18. Đầu ra: giá trị biểu thức.",tests:[{in:"3 4 + 2 * 10 -",out:"4"},{in:"5",out:"5"},{in:"2 3 4 * +",out:"14"},{in:"10 2 - 3 -",out:"5"},{in:"1 2 3 4 5 * * * *",out:"120"},{in:"100000 100000 * 100000 *",out:"1000000000000000"},{in:"0 7 - 3 *",out:"-21"}],start:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    stack<long long> st;\n    string tk;\n    while (cin >> tk) {\n        // số: push; toán tử: lấy b rồi a, push(a op b)\n    }\n    cout << 0 << \"\\n\";\n    return 0;\n}",py:{start:"st = []\nfor tk in input().split():\n    # số: append; toán tử: lấy b rồi a, append(a op b)\n    pass\nprint(0)",hints:["input().split() cho danh sách các ký hiệu.","Gặp toán tử: phần tử lấy ra trước là toán hạng bên PHẢI (b), lấy ra sau là bên trái (a). 10 2 − nghĩa là 10 − 2.","Đừng dùng eval: hãy tự tính bằng ngăn xếp."],needMsg:"Hãy tự tính bằng ngăn xếp, không dùng eval.",need:/^(?![\s\S]*\beval\s*\()/},cs:{start:"using System;\nusing System.Collections.Generic;\n\nclass Program\n{\n    static void Main()\n    {\n        Stack<long> st = new Stack<long>();\n        foreach (string tk in Console.ReadLine().Split())\n        {\n            // số: Push; toán tử: lấy b rồi a, Push(a op b)\n        }\n        Console.WriteLine(0);\n    }\n}",hints:["Console.ReadLine().Split() cho mảng các ký hiệu.","Gặp toán tử: phần tử lấy ra trước là toán hạng bên PHẢI (b), lấy ra sau là bên trái (a). 10 2 − nghĩa là 10 − 2.","long.Parse(tk) đổi chuỗi thành số."]}},{t:"Xóa cặp ký tự kề nhau giống nhau",d:"Cho xâu s gồm chữ cái thường (1 ≤ độ dài ≤ 10^5). Lặp lại: chọn hai ký tự kề nhau giống nhau và xóa cả hai, tới khi không còn cặp nào. Đầu ra: xâu cuối cùng (kết quả không phụ thuộc thứ tự xóa), hoặc EMPTY nếu xâu rỗng. Ví dụ abbaca → aaca → ca.",tests:[{in:"abbaca",out:"ca"},{in:"azxxzy",out:"ay"},{in:"aa",out:"EMPTY"},{in:"abc",out:"abc"},{in:"aabbccdd",out:"EMPTY"},{in:"abccbaab",out:"ab"},{in:"z",out:"z"}],start:"#include <iostream>\n#include <stack>\n#include <string>\nusing namespace std;\n\nint main() {\n    string s;\n    cin >> s;\n    string kq = s;\n    // gợi ý: kq dùng như một ngăn xếp (push_back, back, pop_back)\n    cout << (kq.empty() ? \"EMPTY\" : kq) << \"\\n\";\n    return 0;\n}",perf:{gen:n=>"ab".repeat(n/4)+"ba".repeat(n/4),ns:[500,2000,8000],need:"n",limit:n=>40*n+200,why:"Mỗi lần xóa một cặp rồi quét lại từ đầu là O(n²). Ngăn xếp xử lý mỗi ký tự đúng một lần."},py:{start:"s = input()\nst = []\n# gợi ý: st dùng như một ngăn xếp các ký tự\nkq = \"\".join(st)\nprint(kq if kq else \"EMPTY\")",hints:["Duyệt từng ký tự c: nếu đỉnh ngăn xếp bằng c thì hai ký tự này triệt tiêu (pop); ngược lại append c.","Phần còn lại trong ngăn xếp chính là kết quả, đúng thứ tự: \"\".join(st).","Xóa trực tiếp trên xâu rồi quét lại từ đầu tốn O(n²)."]},cs:{start:"using System;\nusing System.Text;\n\nclass Program\n{\n    static void Main()\n    {\n        string s = Console.ReadLine();\n        StringBuilder kq = new StringBuilder();\n        // gợi ý: kq dùng như một ngăn xếp các ký tự (Append, kq[kq.Length - 1], Remove(kq.Length - 1, 1))\n        Console.WriteLine(kq.Length == 0 ? \"EMPTY\" : kq.ToString());\n    }\n}",hints:["Duyệt từng ký tự c: nếu đỉnh ngăn xếp bằng c thì hai ký tự này triệt tiêu (bỏ đỉnh); ngược lại thêm c.","StringBuilder dùng làm ngăn xếp: Append thêm vào cuối, kq[kq.Length − 1] là đỉnh, kq.Remove(kq.Length − 1, 1) bỏ đỉnh; xóa ở cuối nên O(1).","Xóa trực tiếp trên xâu (Remove) rồi quét lại từ đầu tốn O(n²)."]}}]);

